import { OnboardingForm } from "@/registry/onboarding-kit/onboarding-form"

export default function OnboardingPage() {
  return (
    <div className="h-svh overflow-y-auto">
      <OnboardingForm />
    </div>
  )
}

"use client";

import { useState } from "react";
import { Survey } from "@/components/survey/survey";
import type { QuestionConfig } from "@/components/survey/survey-types";

interface Attrs {
  name?: string;
  role?: string;
  goal?: string;
}

const steps: QuestionConfig<Attrs>[] = [
  {
    id: "name",
    title: "What's your name?",
    type: "text",
    placeholder: "Jane Doe",
  },
  {
    id: "role",
    title: "What's your role?",
    type: "radio",
    variant: "button",
    options: [
      { value: "engineer", label: "Engineer" },
      { value: "designer", label: "Designer" },
      { value: "pm", label: "Product Manager" },
      { value: "founder", label: "Founder" },
    ],
  },
  {
    id: "goal",
    title: "What are you building?",
    type: "textarea",
    placeholder: "Tell us about your project...",
  },
];

export function OnboardingForm() {
  const [attrs, setAttrs] = useState<Attrs>({});
  const [done, setDone] = useState(false);

  if (done) {
    return (
      <div className="flex h-svh items-center justify-center p-8">
        <div className="w-full max-w-lg text-center">
          <h1 className="text-2xl font-bold">Welcome, {attrs.name}!</h1>
          <p className="mt-2 text-muted-foreground">Onboarding complete.</p>
          <pre className="mt-4 overflow-auto rounded bg-muted p-4 text-left text-sm">
            {JSON.stringify(attrs, null, 2)}
          </pre>
        </div>
      </div>
    );
  }

  return (
    <Survey
      questions={steps}
      attributes={attrs}
      onAttributeChange={setAttrs}
      onComplete={(final) => {
        setAttrs(final);
        setDone(true);
      }}
      showProgress
      logo={<span className="text-lg font-bold tracking-tight">My App</span>}
    />
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { FormEvent } from "react";
import { AlertCircle, ArrowLeft } from "lucide-react";
import {
  Questionnaire as QuestionnairePrimitive,
  type QuestionnaireItemDefinition,
  type QuestionnaireShortcutMode,
} from "@shadcn/react/questionnaire";
import { cn } from "@/lib/utils";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Questionnaire,
  QuestionnaireDescription,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/components/ui/questionnaire";
import { SurveyShell } from "./survey-shell";
import { QuestionRenderer } from "./question-renderer";
import { AUTO_ADVANCE_CONFIG } from "./survey-config";
import { resolveQuestionOptions } from "@/hooks/use-question-options";
import type { QuestionConfig } from "./survey-types";

export interface SurveyProps<A extends Record<string, any>> {
  questions: QuestionConfig<A>[];
  /** Current answers. The survey is controlled: every change goes through `onAttributeChange`. */
  attributes: A;
  onAttributeChange: (attributes: A) => void;
  onComplete: (attributes: A) => void;
  /** Question to open first, for resuming a saved draft. Defaults to the first enabled question. */
  defaultQuestionId?: keyof A & string;
  /** Keyboard shortcuts for fixed choices: A, B, C… or 1, 2, 3… */
  shortcuts?: QuestionnaireShortcutMode;
  /** Custom right panel content. Overrides `rightImage`. */
  rightContent?: React.ReactNode;
  /** Shorthand: provide an image URL and it fills the right panel as cover. */
  rightImage?: string;
  /** Hide the right panel and center the survey content. */
  hideRightPanel?: boolean;
  /** Logo image URL for top-left branding. Max height 32px. */
  logoUrl?: string;
  /** Custom logo element (overrides `logoUrl`). */
  logo?: React.ReactNode;
  onBackFromFirstQuestion?: () => void;
  hideContinueButton?: boolean;
  hideQuestionTitle?: boolean;
  showProgress?: boolean;
  /** Label for Continue on every question, including the last. */
  continueLabel?: string;
  className?: string;
}

const isEnabled = <A,>(question: QuestionConfig<A>, attributes: A) =>
  !question.condition || question.condition(attributes);

// Info screens are required too: their hidden answer is always present, so Skip never shows.
const isRequired = <A,>(question: QuestionConfig<A>) => !question.optional;

const sliderMidpoint = <A,>(question: QuestionConfig<A>) => {
  const min = question.sliderProps?.min ?? 0;
  const max = question.sliderProps?.max ?? 10;
  return Math.round((min + max) / 2);
};

/** Answers a question carries without input: info screens and an untouched slider. */
function withImplicitAnswer<A extends Record<string, any>>(
  question: QuestionConfig<A>,
  attributes: A
): A {
  if (question.type === "info" && attributes[question.id] !== true) {
    return { ...attributes, [question.id]: true };
  }
  if (question.type === "slider" && attributes[question.id] === undefined) {
    return { ...attributes, [question.id]: sliderMidpoint(question) };
  }
  return attributes;
}

function validationMessage<A extends Record<string, any>>(
  question: QuestionConfig<A>,
  attributes: A
): string | null {
  if (!question.validationSchema) return null;
  const result = question.validationSchema.safeParse(attributes[question.id]);
  if (result.success) return null;
  return question.validationErrorMessage ?? result.error.issues[0]?.message ?? "Invalid input";
}

export function Survey<A extends Record<string, any>>({
  questions,
  attributes,
  onAttributeChange,
  onComplete,
  defaultQuestionId,
  shortcuts,
  rightContent,
  rightImage,
  hideRightPanel = false,
  logoUrl,
  logo,
  onBackFromFirstQuestion,
  hideContinueButton = false,
  hideQuestionTitle = false,
  showProgress = false,
  continueLabel = "Continue",
  className,
}: SurveyProps<A>) {
  const shellRef = useRef<HTMLDivElement>(null);
  const advanceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const enabledQuestions = useMemo(
    () => questions.filter((q) => isEnabled(q, attributes)),
    [questions, attributes]
  );
  const [activeId, setActiveId] = useState<string | undefined>(defaultQuestionId);
  const [invalid, setInvalid] = useState<{ id: string; message: string } | null>(null);

  // A condition can remove the active question; fall back to the first enabled one.
  const currentId = enabledQuestions.some((q) => q.id === activeId)
    ? activeId
    : enabledQuestions[0]?.id;
  const currentIndex = enabledQuestions.findIndex((q) => q.id === currentId);
  const currentQuestion = enabledQuestions[currentIndex];

  const items = useMemo<QuestionnaireItemDefinition[]>(
    () =>
      questions.map((q) => ({
        name: q.id,
        required: isRequired(q),
        disabled: !isEnabled(q, attributes),
        choices: resolveQuestionOptions(q, attributes).map((option) => ({
          value: String(option.value),
        })),
      })),
    [questions, attributes]
  );

  const cancelAdvance = useCallback(() => {
    if (advanceTimer.current) clearTimeout(advanceTimer.current);
    advanceTimer.current = null;
  }, []);

  useEffect(() => cancelAdvance, [cancelAdvance]);
  useEffect(() => cancelAdvance(), [currentId, cancelAdvance]);

  /** Moves on through Questionnaire's own Continue button, so its validation still runs. */
  const advance = useCallback(() => {
    const action = shellRef.current?.querySelector<HTMLButtonElement>(
      '[data-survey-action][data-visible]:not(:disabled)'
    );
    action?.click();
  }, []);

  const scheduleAdvance = useCallback(() => {
    cancelAdvance();
    advanceTimer.current = setTimeout(advance, AUTO_ADVANCE_CONFIG.TOTAL_DELAY);
  }, [advance, cancelAdvance]);

  const answer = (question: QuestionConfig<A>, value: unknown) => {
    setInvalid((current) => (current?.id === question.id ? null : current));
    onAttributeChange({ ...attributes, [question.id]: value });
  };

  const handleItemChange = (nextId: string) => {
    const nextIndex = enabledQuestions.findIndex((q) => q.id === nextId);
    if (currentQuestion && nextIndex > currentIndex) {
      const committed = withImplicitAnswer(currentQuestion, attributes);
      const message = validationMessage(currentQuestion, committed);
      if (message) {
        setInvalid({ id: currentQuestion.id, message });
        return;
      }
      if (committed !== attributes) onAttributeChange(committed);
    }
    setInvalid(null);
    setActiveId(nextId);
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    cancelAdvance();
    const committed = currentQuestion
      ? withImplicitAnswer(currentQuestion, attributes)
      : attributes;
    for (const question of enabledQuestions) {
      const message = validationMessage(question, committed);
      if (message) {
        setInvalid({ id: question.id, message });
        setActiveId(question.id);
        return;
      }
    }
    onComplete(committed);
  };

  // Resolve right panel: hidden > explicit content > image shorthand > default placeholder
  const resolvedRightContent = hideRightPanel
    ? undefined
    : rightContent ??
      (rightImage ? (
        <div className="relative h-full w-full overflow-hidden rounded-2xl">
          <img src={rightImage} alt="" className="size-full object-cover" />
          <div className="absolute inset-0 rounded-2xl ring-1 ring-inset ring-foreground/5" />
        </div>
      ) : (
        <div className="relative h-full w-full overflow-hidden rounded-2xl bg-muted">
          <img
            src="/placeholder.svg"
            alt=""
            className="absolute inset-0 h-full w-full object-cover dark:invert"
          />
          <div className="absolute inset-0 rounded-2xl ring-1 ring-inset ring-foreground/5" />
        </div>
      ));

  if (!currentQuestion) return null;

  const backClassName = "flex-1 md:size-10 md:flex-none md:px-0";
  // Continue stays unavailable until the question is answered (or skipped).
  const continueRender = (
    props: React.ComponentProps<"button">,
    state: { status: string | null }
  ) => <button {...props} disabled={props.disabled || state.status === "unanswered"} />;
  const continueClassName = cn(
    "flex-1 md:ms-auto md:flex-none",
    "md:data-[status=unanswered]:invisible",
    hideContinueButton && "sr-only"
  );

  return (
    <Questionnaire
      item={currentId}
      items={items}
      onItemChange={handleItemChange}
      onSubmit={handleSubmit}
      shortcuts={shortcuts}
      className={cn("min-h-full gap-0", className)}
    >
      <SurveyShell
        ref={shellRef}
        className="flex-1"
        rightContent={resolvedRightContent}
        logo={logo}
        logoUrl={logoUrl}
        progress={
          showProgress ? (
            <QuestionnairePrimitive.Progress
              render={(props, state) => (
                <div
                  {...props}
                  className="mt-2 h-1.5 w-24 overflow-hidden rounded-full bg-foreground/10"
                >
                  <div
                    className="h-full rounded-full bg-primary transition-[width] duration-300"
                    style={{ width: `${state.total ? (state.current / state.total) * 100 : 0}%` }}
                  />
                </div>
              )}
            />
          ) : undefined
        }
        actions={
          <div className="mx-auto flex w-full max-w-lg items-center gap-3">
            {currentIndex === 0 && onBackFromFirstQuestion && (
              <Button
                type="button"
                variant="outline"
                size="lg"
                className={backClassName}
                onClick={onBackFromFirstQuestion}
              >
                <ArrowLeft />
                <span className="md:sr-only">Back</span>
              </Button>
            )}
            <QuestionnairePrevious variant="outline" size="lg" className={backClassName}>
              <ArrowLeft />
              <span className="md:sr-only">Back</span>
            </QuestionnairePrevious>
            <QuestionnaireSkip variant="ghost" size="lg" className="md:ms-auto">
              Skip
            </QuestionnaireSkip>
            <QuestionnaireNext
              data-survey-action="next"
              size="lg"
              className={continueClassName}
              render={continueRender}
            >
              {continueLabel}
            </QuestionnaireNext>
            <QuestionnaireSubmit
              data-survey-action="submit"
              size="lg"
              className={continueClassName}
              render={continueRender}
            >
              {continueLabel}
            </QuestionnaireSubmit>
          </div>
        }
      >
        <div className="mx-auto w-full max-w-lg py-6">
          {questions.map((question) => {
            const active = question.id === currentId;
            return (
              <QuestionnaireItem
                key={question.id}
                name={question.id}
                required={isRequired(question)}
                disabled={!isEnabled(question, attributes)}
                multiple={
                  question.type === "card-checkbox" &&
                  !question.cardCheckboxProps?.singleSelection
                }
                invalid={invalid?.id === question.id}
                className="gap-0 data-active:animate-in data-active:fade-in-0 data-active:slide-in-from-bottom-2 data-active:duration-300"
              >
                <QuestionnaireTitle
                  className={cn(
                    "mb-0 max-w-lg font-heading text-2xl font-semibold tracking-tight text-foreground md:text-3xl",
                    !question.description && "mb-6",
                    hideQuestionTitle && "sr-only"
                  )}
                >
                  {question.title}
                </QuestionnaireTitle>
                {question.description && (
                  <QuestionnaireDescription className="mt-3 mb-6 max-w-lg text-base leading-relaxed">
                    {question.description}
                  </QuestionnaireDescription>
                )}
                <QuestionRenderer
                  question={question}
                  attributes={attributes}
                  isActive={active}
                  value={attributes[question.id]}
                  onChange={(value) => answer(question, value)}
                  onAutoAdvance={active ? scheduleAdvance : undefined}
                  onSubmitText={advance}
                />
                <QuestionnairePrimitive.Error
                  render={<Alert variant="destructive" className="mt-4" />}
                >
                  <AlertCircle />
                  <AlertDescription>
                    {invalid?.id === question.id
                      ? invalid.message
                      : "Answer this question to continue."}
                  </AlertDescription>
                </QuestionnairePrimitive.Error>
              </QuestionnaireItem>
            );
          })}
        </div>
      </SurveyShell>
    </Questionnaire>
  );
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { Progress } from "@/components/ui/progress";

/* ---------------------------------- Types --------------------------------- */

export interface SurveyShellProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  rightContent?: React.ReactNode;
  logoUrl?: string;
  logo?: React.ReactNode;
  /** Progress indicator rendered under the logo. */
  progress?: React.ReactNode;
  /** @deprecated Pass `progress` instead. */
  showProgress?: boolean;
  /** @deprecated Pass `progress` instead. */
  progressPercent?: number;
  actions?: React.ReactNode;
}

/* -------------------------------- Component ------------------------------- */

const SurveyShell = React.forwardRef<HTMLDivElement, SurveyShellProps>(
  ({ className, children, rightContent, logoUrl, logo, progress, showProgress, progressPercent, actions, ...props }, ref) => {
    const resolvedLogo = logo ?? (logoUrl ? (
      <img src={logoUrl} alt="Logo" className="max-h-8 w-auto" />
    ) : null);

    const resolvedProgress =
      progress ??
      (showProgress && progressPercent !== undefined ? (
        <Progress value={progressPercent} className="mt-2 h-1.5 w-24" />
      ) : null);

    const hasHeader = resolvedLogo || resolvedProgress;

    return (
      <div
        ref={ref}
        className={cn("flex min-h-full w-full", className)}
        {...props}
      >
        {/*
          Left panel — single overflow-y-auto container.
          Scrollbar sits at the right edge (between left and right panels).
          Header and actions use sticky positioning within the scroll flow.
          Pattern from Diino's StickToBottom + StickyChatContainer.
        */}
        <div
          className={cn(
            "relative",
            rightContent ? "w-full md:w-1/2" : "mx-auto w-full max-w-2xl"
          )}
        >
          <div className="flex min-h-full flex-col">
            {/* Header — sticky top */}
            {hasHeader && (
              <div className="sticky top-0 z-20 bg-inherit px-8 pt-6 pb-3 md:px-12 md:pt-8">
                <div className="mx-auto w-full max-w-lg">
                  {resolvedLogo}
                  {resolvedProgress}
                </div>
              </div>
            )}

            {/* Content — flex-1 + justify-end pushes content to bottom like Diino's chat feed */}
            <div className="flex min-h-0 flex-1 flex-col justify-end px-8 md:px-12">
              {children}
            </div>

            {/* Actions — sticky bottom (like StickyChatContainer) */}
            {actions && (
              <div className="sticky bottom-0 z-20 bg-inherit px-8 pb-6 pt-4 md:px-12 md:pb-8">
                {actions}
              </div>
            )}
          </div>
        </div>

        {/* Right panel — static, no scroll */}
        {rightContent && (
          <div className="sticky top-0 hidden max-h-dvh shrink-0 md:flex md:w-1/2 md:p-4">
            {rightContent}
          </div>
        )}
      </div>
    );
  }
);
SurveyShell.displayName = "SurveyShell";

/* ------------------------------ Sub-components ----------------------------- */

export interface SurveyQuestionProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title: string;
  description?: string;
  children: React.ReactNode;
  active?: boolean;
  hideQuestionTitle?: boolean;
}

const SurveyQuestion = React.forwardRef<HTMLDivElement, SurveyQuestionProps>(
  (
    {
      className,
      title,
      description,
      children,
      active = true,
      hideQuestionTitle,
      ...props
    },
    ref
  ) => (
    <div
      ref={ref}
      className={cn("w-full", !active && "opacity-60", className)}
      {...props}
    >
      {!hideQuestionTitle && (
        <h2 className={cn("max-w-lg font-heading text-2xl font-semibold tracking-tight text-foreground md:text-3xl", !description && "mb-6")}>
          {title}
        </h2>
      )}
      {description && (
        <p className="mt-3 mb-6 max-w-lg leading-relaxed text-muted-foreground">
          {description}
        </p>
      )}
      <div className={cn(!active && "pointer-events-none")}>{children}</div>
    </div>
  )
);
SurveyQuestion.displayName = "SurveyQuestion";

const SurveyRightPanel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, children, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("flex h-full w-full items-center justify-center", className)}
    {...props}
  >
    {children}
  </div>
));
SurveyRightPanel.displayName = "SurveyRightPanel";

export { SurveyShell, SurveyQuestion, SurveyRightPanel };

"use client";

import { Questionnaire as QuestionnairePrimitive } from "@shadcn/react/questionnaire";
import { TextInputQuestion } from "./text-input-question";
import { TextareaQuestion } from "./textarea-question";
import { RadioQuestion } from "./radio-question";
import { CardCheckboxQuestion } from "./card-checkbox-question";
import { SliderQuestion } from "./slider-question";
import { RatingQuestion } from "./rating-question";
import type { QuestionConfig, CardOption } from "./survey-types";
import { useQuestionOptions } from "@/hooks/use-question-options";

interface QuestionRendererProps<A = any> {
  question: QuestionConfig<A>;
  attributes: A;
  /** Whether this is the question on screen. */
  isActive: boolean;
  value: any;
  onChange: (value: any) => void;
  /** Schedules auto-advance after a pointer selection on single-choice questions. */
  onAutoAdvance?: () => void;
  /** Continues from a text answer (the inline arrow button). */
  onSubmitText?: () => void;
}

/** The answer control for one question, built from Questionnaire parts. */
export function QuestionRenderer<A>({
  question,
  attributes,
  isActive,
  value,
  onChange,
  onAutoAdvance,
  onSubmitText,
}: QuestionRendererProps<A>) {
  const { options, error } = useQuestionOptions(question, attributes);
  const inputId = `survey-${question.id}`;

  if (error) {
    return (
      <div className="py-4 text-destructive">
        <p>Error loading options: {error}</p>
      </div>
    );
  }

  switch (question.type) {
    case "info":
      // Nothing to answer: a fixed hidden answer lets Continue proceed.
      return (
        <QuestionnairePrimitive.Input
          value="true"
          readOnly
          tabIndex={-1}
          aria-hidden
          className="sr-only"
        />
      );

    case "text":
      return (
        <TextInputQuestion
          id={inputId}
          value={(value as string) ?? ""}
          onChange={onChange}
          onSubmit={isActive ? onSubmitText : undefined}
          placeholder={question.placeholder}
          placeholders={question.placeholders}
          ariaLabel={question.title}
        />
      );

    case "number":
      return (
        <TextInputQuestion
          id={inputId}
          type="number"
          value={value?.toString() ?? ""}
          onChange={(val) => onChange(val ? parseInt(val, 10) : undefined)}
          onSubmit={isActive ? onSubmitText : undefined}
          placeholder={question.placeholder}
          ariaLabel={question.title}
        />
      );

    case "radio":
      return (
        <RadioQuestion
          options={options.map((opt) => ({ ...opt, value: String(opt.value) }))}
          value={value === undefined || value === null ? "" : String(value)}
          onChange={onChange}
          onAutoAdvance={onAutoAdvance}
          variant={question.variant}
        />
      );

    case "boolean":
      return (
        <RadioQuestion
          options={options.map((opt) => ({ ...opt, value: String(opt.value) }))}
          value={value === true ? "true" : value === false ? "false" : ""}
          onChange={(val: string) => onChange(val === "true")}
          onAutoAdvance={onAutoAdvance}
        />
      );

    case "card-checkbox": {
      const single = question.cardCheckboxProps?.singleSelection ?? false;
      return (
        <CardCheckboxQuestion
          options={options as CardOption[]}
          singleSelection={single}
          values={single ? (value ? [value as string] : []) : Array.isArray(value) ? value : []}
          onChange={(values: string[]) =>
            onChange(single ? values[values.length - 1] : values)
          }
          onAutoAdvance={onAutoAdvance}
        />
      );
    }

    case "textarea":
      return (
        <TextareaQuestion
          id={inputId}
          value={(value as string) ?? ""}
          onChange={onChange}
          placeholder={question.placeholder}
          ariaLabel={question.title}
        />
      );

    case "slider": {
      const sp = question.sliderProps;
      return (
        <SliderQuestion
          id={inputId}
          value={value as number | undefined}
          onChange={onChange}
          min={sp?.min}
          max={sp?.max}
          step={sp?.step}
          minLabel={sp?.minLabel}
          maxLabel={sp?.maxLabel}
          ariaLabel={question.title}
        />
      );
    }

    case "rating":
      return (
        <RatingQuestion
          value={value as number | undefined}
          onChange={onChange}
          max={question.ratingProps?.max}
          onAutoAdvance={onAutoAdvance}
        />
      );

    default:
      return (
        <div className="text-muted-foreground">
          Unsupported question type: {question.type}
        </div>
      );
  }
}

"use client";

import { useRef, useState } from "react";
import { motion } from "motion/react";
import { Questionnaire as QuestionnairePrimitive } from "@shadcn/react/questionnaire";
import { cn } from "@/lib/utils";
import { CheckIndicator } from "./check-indicator";
import { AUTO_ADVANCE_CONFIG } from "./survey-config";

interface RadioOption {
  value: string;
  label: string;
  emoji?: string;
  icon?: React.ComponentType<{ className?: string }>;
  description?: string;
}

interface RadioQuestionProps {
  options: RadioOption[];
  value: string;
  onChange: (value: string) => void;
  className?: string;
  /** Called after a pointer selection; keyboard users continue with Enter. */
  onAutoAdvance?: () => void;
  disabled?: boolean;
  variant?: "button" | "card";
}

/** Fills the choice left to right while auto-advance waits. */
function SelectionSweep() {
  return (
    <motion.div
      aria-hidden
      className="pointer-events-none absolute inset-0 z-0 origin-left bg-primary/5 will-change-transform"
      initial={{ scaleX: 0 }}
      animate={{ scaleX: 1 }}
      transition={{ duration: AUTO_ADVANCE_CONFIG.ANIMATION_DURATION / 1000, ease: "linear" }}
    />
  );
}

/** Tracks whether the latest selection came from a pointer, for auto-advance. */
export function useAutoAdvanceSelection(onAutoAdvance?: () => void) {
  const fromPointer = useRef(false);
  const [sweeping, setSweeping] = useState<string | null>(null);

  const choiceProps = {
    onPointerDown: () => {
      fromPointer.current = true;
    },
    onKeyDown: () => {
      fromPointer.current = false;
    },
  };

  const selected = (value: string) => {
    if (fromPointer.current && onAutoAdvance) {
      setSweeping(value);
      setTimeout(() => setSweeping(null), AUTO_ADVANCE_CONFIG.TOTAL_DELAY);
      onAutoAdvance();
    }
    fromPointer.current = false;
  };

  return { choiceProps, selected, sweeping };
}

export function RadioQuestion({
  options,
  value,
  onChange,
  className,
  onAutoAdvance,
  disabled = false,
  variant = "button",
}: RadioQuestionProps) {
