import type { z } from "zod";

export interface CardOption {
  value: string;
  label: string;
  description?: string;
  imageUrl?: string;
}

export interface BaseOption {
  value: string | boolean;
  label: string;
  imageUrl?: string;
  emoji?: string;
  icon?: React.ComponentType<{ className?: string }>;
  description?: string;
}

export type SyncOptions<T = BaseOption> = T[];
export type SyncOptionsFunction<T = BaseOption, A = any> = (attrs: A) => T[];
export type QuestionOptions<T = BaseOption, A = any> =
  | SyncOptions<T>
  | SyncOptionsFunction<T, A>;

export interface OptionsLoadingState<T = BaseOption> {
  options: T[];
  loading: boolean;
  error: string | null;
}

export interface QuestionConfig<A = any> {
  id: keyof A & string;
  title: string;
  description?: string;
  type: "text" | "number" | "textarea" | "radio" | "boolean" | "card-checkbox" | "slider" | "rating" | "info";
  options?: QuestionOptions<any, A>;
  condition?: (attributes: A) => boolean;
  optional?: boolean;
  /** Radio display style — "button" (vertical list) or "card" (2-col grid). */
  variant?: "button" | "card";
  /** Static placeholder for text inputs. */
  placeholder?: string;
  /** Rotating typewriter placeholders for text inputs. */
  placeholders?: string[];
  cardCheckboxProps?: {
    singleSelection?: boolean;
  };
  sliderProps?: {
    min?: number;
    max?: number;
    step?: number;
    /** Labels for min and max ends. */
    minLabel?: string;
    maxLabel?: string;
  };
  ratingProps?: {
    /** Number of stars/items. Default 5. */
    max?: number;
  };
  validationSchema?: z.ZodSchema;
  validationErrorMessage?: string;
}

/**
 * Centralized timing config for survey auto-advance.
 */

export const AUTO_ADVANCE_CONFIG = {
  /** Duration of the selection animation (ms). */
  ANIMATION_DURATION: 800,
  /** Total wait before auto-advancing to the next question (ms). */
  TOTAL_DELAY: 1000,
} as const;

import { useMemo } from "react";
import type {
  QuestionConfig,
  OptionsLoadingState,
  BaseOption,
  SyncOptionsFunction,
} from "@/components/survey/survey-types";

/** A question's options for the current answers: a static list, or computed from them. */
export function resolveQuestionOptions<T extends BaseOption, A = any>(
  question: QuestionConfig<A>,
  attributes: A
): T[] {
  if (question.type === "boolean") {
    return [
      { value: "true", label: "Yes" },
      { value: "false", label: "No" },
    ] as T[];
  }
  if (question.type === "rating") {
    const max = question.ratingProps?.max ?? 5;
    return Array.from({ length: max }, (_, i) => ({
      value: String(i + 1),
      label: `${i + 1} of ${max}`,
    })) as T[];
  }
  if (!question.options) return [];
  if (Array.isArray(question.options)) return question.options as T[];
  return (question.options as SyncOptionsFunction<T, A>)(attributes);
}

export function useQuestionOptions<T extends BaseOption, A = any>(
  question: QuestionConfig<A>,
  attributes: A
): OptionsLoadingState<T> {
  const options = useMemo(
    () => resolveQuestionOptions<T, A>(question, attributes),
    [question, attributes]
  );

  return { options, loading: false, error: null };
}
